  Lemma of_segH3 : forall vals R M,
    length vals = 231%nat -> vals_ev vals 0 = sp0 ->
    regs_ok (ENV BL vals) srH30 R -> know_ok RSEGS (ENV BL vals) M knH30 ->
    srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0xd8830) M (seg_rom RSEGS)) model)
